  ('cf7a69de-5cc3-5bcf-a244-2c718469d3cf', 'b1cc670c-e099-5600-93ef-793a69d710b0', 'a7815140-79c2-5fd6-bdcb-5598d90f711b', 'out', 'template', 'slot_offer', 'Thanks. Here are open afternoon times. Reply with a number: 1) Thu 2:00 PM 2) Fri 1:00 PM 3) Mon 3:00 PM', 1, 'MOCK-SM-RB-02-3', 'delivered', now() - interval '131 minutes'),
