  ('066fa441-f6f4-55d2-b417-d8775381fb68', 'b1cc670c-e099-5600-93ef-793a69d710b0', 'a7815140-79c2-5fd6-bdcb-5598d90f711b', 'out', 'template', 'request_received', 'Got it, Thu 2:00 PM is requested. We''ll text you a confirmation shortly. Reply STOP to opt out.', 1, 'MOCK-SM-RB-02-5', 'delivered', now() - interval '129 minutes'),
