  ('9ba5690f-4612-54f5-ade3-aafedb969dbc', '1e61deb3-3314-5971-aa2e-a5c01f91acf5', 'ae2033d8-ee72-567c-aa5d-73ca7b67186a', 'in', 'customer', null, 'how much for a small wrist tattoo?', 1, 'MOCK-SM-NL-02-1', 'received', now() - interval '85 minutes'),
  ('6d93c093-db65-5470-beed-1b04febd02ca', '1e61deb3-3314-5971-aa2e-a5c01f91acf5', 'a5976920-6290-5acb-a9aa-07d557335500', 'out', 'template', 'slot_offer', 'Thanks, Kira. Here are open touch-up times with Mara. Reply with a number: 1) Fri 11:00 AM 2) Sat 2:00 PM 3) Tue 12:00 PM', 1, 'MOCK-SM-NL-03-1', 'delivered', now() - interval '38 minutes'),
  ('2753725f-cf0c-5470-97c2-e95efe888241', '1e61deb3-3314-5971-aa2e-a5c01f91acf5', '043f29c6-9cf1-5a29-868a-fe3656e37d34', 'out', 'template', 'missed_call_text_back', 'Sorry we missed your call! This is Northline Ink. Sounds like you''d like a nose piercing. What day and time works best? Reply STOP to opt out.', 1, 'MOCK-SM-NL-04-1', 'delivered', now() - interval '129 minutes'),
