  ('88b59164-1274-5750-ba0c-0261b5be4934', '72861613-42bb-5953-b39b-a821a84d3caa', '79111375-807d-5094-8a17-66069620dfa4', 'out', 'template', 'missed_call_text_back', 'Thanks, Prairie Path Counseling received your request. Our front desk will confirm a time with you. Reply STOP to opt out.', 1, 'MOCK-SM-PP-02-1', 'delivered', now() - interval '398 minutes'),
  ('23b899ed-7c85-51e5-9482-79fdba170dd9', '72861613-42bb-5953-b39b-a821a84d3caa', 'c285b3f4-f26f-5987-a65d-a183a013f796', 'in', 'customer', null, 'I need to cancel Thursday, sorry.', 1, 'MOCK-SM-PP-03-1', 'received', now() - interval '150 minutes'),
  ('e029aed6-4b6a-502f-b51e-71f3cea12712', '72861613-42bb-5953-b39b-a821a84d3caa', '8b7f3727-f477-5e7f-aa69-5391ce688de4', 'out', 'template', 'slot_offer', 'Prairie Path Counseling has an opening from the waitlist. Reply with a number: 1) Thu 10:00 AM 2) Fri 2:00 PM. Reply STOP to opt out.', 1, 'MOCK-SM-PP-04-1', 'delivered', now() - interval '138 minutes'),
  ('334bbb0e-44ff-5ea3-b8d4-d870ab2afa36', '72861613-42bb-5953-b39b-a821a84d3caa', 'd83584ff-aeb1-5508-886d-f9196b56a144', 'out', 'template', 'confirmation', 'You''re booked with Prairie Path Counseling for Wed 10:00 AM. Reply STOP to opt out.', 1, 'MOCK-SM-PP-05-1', 'delivered', now() - interval '1960 minutes'),
  ('8affb097-c5c9-5e3a-a7cc-9abd499492dd', '72861613-42bb-5953-b39b-a821a84d3caa', '543e6224-77bc-5b64-bf86-8a78542db9df', 'in', 'customer', null, 'Can I come in sooner? This week has been really hard.', 1, 'MOCK-SM-PP-06-1', 'received', now() - interval '95 minutes'),
  ('9ffb61e3-5108-5597-a82c-93596a36c981', '72861613-42bb-5953-b39b-a821a84d3caa', '55e14f81-fd8d-5d31-a935-09830ebd20e2', 'in', 'customer', null, 'I don''t know if I can keep going.', 1, 'MOCK-SM-PP-07-1', 'received', now() - interval '600 minutes'),
  ('b525b618-746c-5e74-8eb9-22c7cf9e4b02', '72861613-42bb-5953-b39b-a821a84d3caa', '55e14f81-fd8d-5d31-a935-09830ebd20e2', 'out', 'template', 'crisis_message', 'If you are thinking about suicide or are in crisis, call or text 988 to reach the Suicide & Crisis Lifeline. If you are in danger right now, call 911. Prairie Path Counseling''s front desk will see your message when the office opens.', 2, 'MOCK-SM-PP-07-2', 'delivered', now() - interval '599 minutes'),
